import sys, dis, numpy as np
from xarray.core import formatting

vars={'count','num_front','num_back','pprint_str','padding','max_len'}
co = formatting.format_array_flat.__code__
ins = list(dis.get_instructions(formatting.format_array_flat))
offset_to = {i.offset:i for i in ins}

pairs=set()


def run(width):
    last_def={}
    def tracer(frame,event,arg):
        nonlocal last_def
        if event=='call' and frame.f_code is co:
            frame.f_trace_opcodes = True
            return tracer
        if frame.f_code is not co:
            return tracer
        if event=='opcode':
            i=offset_to.get(frame.f_lasti)
            if i is None:
                return tracer
            op=i.opname
            if op in {'LOAD_FAST','LOAD_DEREF','LOAD_NAME'} and i.argval in vars:
                v=i.argval
                if v in last_def:
                    pairs.add((v,last_def[v],i.starts_line))
            elif op in {'STORE_FAST','STORE_DEREF','STORE_NAME'} and i.argval in vars:
                v=i.argval
                # starts_line may be None for multi-op line; infer current line
                line = i.starts_line if i.starts_line is not None else frame.f_lineno
                last_def[v]=line
        return tracer
    sys.settrace(tracer)
    arr=np.array([10,20,30,40,50,60,70],dtype=np.int64)
    formatting.format_array_flat(arr,width)
    sys.settrace(None)

for w in [11,80,3]:
    run(w)

for p in sorted(pairs, key=lambda t:(t[0],t[1],t[2] if t[2] is not None else -1)):
    print(p)
